/// <summary>
///  This is a event handler for the TAMRebateDeal form.
/// </summary>
class METTAMRebateDealEventHandler
{   
}

Method.Source:
    /// <summary>
    /// Initializing the rebate table values.
    /// </summary>
    /// <param name="sender">Sender</param>
    /// <param name="e">Event</param>
    [FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateTable), FormDataSourceEventType::InitValue),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void TAMRebateTable_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateTable rebateTable = sender.cursor();

        TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal, true);

        if (rebateDeal.METVolumetricTierDeal == NoYes::Yes)
        {
            TAMRebateTable rebateTableLoc;

            select firstonly METTierLineType, RecId from rebateTableLoc
                where rebateTableLoc.RebateDeal == rebateTable.RebateDeal;

            if (rebateTableLoc.RecId && rebateTableLoc.METTierLineType == METTierLineType::Rate)
            {
                rebateTable.METTierLineType = METTierLineType::Value;
            }
            else if (rebateTableLoc.RecId &&  rebateTableLoc.METTierLineType == METTierLineType::Value)
            {
                rebateTable.METTierLineType = METTierLineType::Rate;
            }

            rebateTable.CalculationMethod = TAMRebateCalcMethod::Cumulative;
            rebateTable.RebateBasis = TAMRebateBasis::Value;

            // Bug 289019: CB201 - Volumetric Tier Rebates - Transactions Type not default to "Invoice"
            rebateTable.SourceType = TAMRebateSourceType::Invoice;

            if (rebateTable.METTierLineType == METTierLineType::Rate)
            {                
                rebateTable.UnitId = "";
                rebateTable.MinimumAmount = 0.00;
                rebateTable.Category = 0;
                rebateTable.RebatePostingId = "";
                rebateTable.GuaranteePostingId = "";
                rebateTable.IncludeTax = NoYes::No;
                rebateTable.IncludeCreditNote = NoYes::Yes;
                rebateTable.IncludeDiscountedAmount = NoYes::No;
                rebateTable.PaidInvoices = NoYes::No;
                rebateTable.IncludeFreeText = NoYes::No;
                rebateTable.IncludeSettlementDiscount = NoYes::No;
                rebateTable.SupportNegativeTier = NoYes::No;
                rebateTable.DocumentNotes = "";
            }
        }
        
        if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend) // CB234, This If condition is for Vendor rebate alone
        {
            METTAMRebateDealEventHandler::setVendRebate(rebateTable, rebateDeal);
        }

        // Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
        // When use external sales data set the transaction type to "External sales data"
        if (rebateDeal.METUseExternalSellData)
        {
            rebateTable.SourceType = TAMRebateSourceType::METExternalSalesData;
        }
    }

    /// <summary>
    /// Enable/Disable the controls values on the rebate date when intializing.
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">Event</param>
    [FormDataSourceEventHandler(formDataSourceStr(TAMRebateDeal, TAMRebateDate), FormDataSourceEventType::InitValue),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void TAMRebateDate_OnInitValue(FormDataSource sender, FormDataSourceEventArgs e)
    {
        TAMRebateDate rebateDate = sender.cursor();
        TAMRebateTable rebateTable = TAMRebateTable::find(rebateDate.RebateId);
        TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);

        if (rebateDeal.METVolumetricTierDeal == NoYes::Yes && rebateTable.METTierLineType == METTierLineType::Rate)
        {
            rebateDate.RebateFromDate = rebateDeal.RebateFromDate;
            rebateDate.RebateToDate = rebateDeal.RebateToDate;
            rebateDate.RebatePer = 1;
            rebateDate.RebatePeriodCode = TAMRebatePeriodCode::Week;
            rebateDate.RebateStartingDayOfWeek = WeekDays::Sunday;
            rebateDate.RebateClaimBy = TAMRebatePeriodCode::Period;
            rebateDate.RebateClaimPer = 1;
            rebateDate.METAvgBy454Week = NoYes::Yes;
            rebateDate.ProcessPosting = NoYes::No;
        }
        
    }

    /// <summary>
    /// Set Vendor rebate related fields
    /// </summary>
    /// <param name = "_rebateTable">TAMRebateTable</param>
    /// <param name = "_rebateDeal">TAMRebateDeal</param>
    public static void setVendRebate(TAMRebateTable _rebateTable, TAMRebateDeal _rebateDeal)
    {
        TAMRebateParameters tamRebateParameters;

        select firstonly METAllowPriceAttributeSelectionOnVendorDeals, METPriceComponentCode, METPurchaseOrderBasis, METSalesOrderBasis
                from tamRebateParameters;

        if (tamRebateParameters.METAllowPriceAttributeSelectionOnVendorDeals)
        {
            _rebateTable.AccountCode = TableGroupAll::All;
            _rebateTable.ItemCode = TableGroupAll::All;
            _rebateTable.METPriceComponentCode = tamRebateParameters.METPriceComponentCode;

            if (_rebateTable.METPriceComponentCode)
            {
                if (_rebateTable.RebateBasisVend == TAMRebateBasisVend::Purch)
                {
                    _rebateTable.METPriceAttributeGroupCombination = tamRebateParameters.METPurchaseOrderBasis;

                    GUPPriceComponentCodePriceAttributeGroupCombination gupPriceComponentCodePriceAttributeGroupCombination;

                    select firstonly RecId, HeaderPriceAttributeGroupName, LinePriceAttributeGroupName  from gupPriceComponentCodePriceAttributeGroupCombination
                            where gupPriceComponentCodePriceAttributeGroupCombination.Name == tamRebateParameters.METPurchaseOrderBasis
                            && gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCodeName == tamRebateParameters.METPriceComponentCode;

                    _rebateTable.PriceComponentCombination = gupPriceComponentCodePriceAttributeGroupCombination.RecId;
                    _rebateTable.METHeaderPriceAttributeGroup = gupPriceComponentCodePriceAttributeGroupCombination.HeaderPriceAttributeGroupName;
                    _rebateTable.METLinePriceAttributeGroup = gupPriceComponentCodePriceAttributeGroupCombination.LinePriceAttributeGroupName;

                }
                else if(_rebateTable.RebateBasisVend == TAMRebateBasisVend::Sales)
                {
                    _rebateTable.METPriceAttributeGroupCombination = tamRebateParameters.METSalesOrderBasis;

                    GUPPriceComponentCodePriceAttributeGroupCombination gupPriceComponentCodePriceAttributeGroupCombination;

                    select firstonly RecId, HeaderPriceAttributeGroupName, LinePriceAttributeGroupName from gupPriceComponentCodePriceAttributeGroupCombination
                            where gupPriceComponentCodePriceAttributeGroupCombination.Name == tamRebateParameters.METSalesOrderBasis
                            && gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCodeName == tamRebateParameters.METPriceComponentCode;

                    _rebateTable.PriceComponentCombination = gupPriceComponentCodePriceAttributeGroupCombination.RecId;
                    _rebateTable.METHeaderPriceAttributeGroup = gupPriceComponentCodePriceAttributeGroupCombination.HeaderPriceAttributeGroupName;
                    _rebateTable.METLinePriceAttributeGroup = gupPriceComponentCodePriceAttributeGroupCombination.LinePriceAttributeGroupName;
                }
                   
                if (!_rebateTable.PricingRuleHeader)
                {
                    GUPPricingRule pricingRule;

                    select firstonly pricingRule
                            where pricingRule.PriceAttributeGroupName == _rebateTable.METHeaderPriceAttributeGroup;

                    _rebateTable.PricingRuleHeader = pricingRule.RecId;
                }
                if (!_rebateTable.PricingRuleLine)
                {
                    GUPPricingRule pricingRule;

                    select firstonly pricingRule
                            where pricingRule.PriceAttributeGroupName == _rebateTable.METLinePriceAttributeGroup;

                    _rebateTable.PricingRuleLine = pricingRule.RecId;
                }

                _rebateTable.METVendAccount = _rebateDeal.METVendAccount;
            }
        }
    }

    /// <summary>
    /// This gets triggered when Vendor rebate basis is modified
    /// </summary>
    /// <param name="sender">FormControl</param>
    /// <param name="e">FormControlEventArgs</param>
    [FormControlEventHandler(formControlStr(TAMRebateDeal, Vend_RebateBasisVend), FormControlEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void Vend_RebateBasisVend_OnModified(FormControl sender, FormControlEventArgs e)
    {
        TAMRebateTable rebateTable = sender.formRun().dataSource(formDataSourceStr(TAMRebateDeal, TAMRebateTable)).cursor();
        TAMRebateDeal rebateDeal = TAMRebateDeal::find(rebateTable.RebateDeal);

        //Bug 220420: CB234 - Updating supplier rebate basis value on an existing vendor rebate - Start
        if(rebateTable)
        {
            ttsbegin;
            rebateTable.selectForUpdate(true);
            rebateTable.PricingRuleHeader = 0;
            rebateTable.PricingRuleLine = 0;
            rebateTable.update();
            ttscommit;
        }

        if (rebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend)
        {
            METTAMRebateDealEventHandler::setVendRebate(rebateTable, rebateDeal);

            FormDataSource TAMRebateTable_DS = sender.formRun().dataSource(formDataSourceStr(TAMRebateDeal, TAMRebateTable));

            TAMRebateTable_DS.write();
        }
        //End
    }

    /// <summary>
    /// This event will be triggered when user will click Lines tab page
    /// </summary>
    /// <param name="sender">FormControl</param>
    /// <param name="e">FormControlEventArgs</param>
    [FormControlEventHandler(formControlStr(TAMRebateDeal, LineViewLines), FormControlEventType::PageActivated),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void LineViewLines_OnPageActivated(FormControl sender, FormControlEventArgs e)
    {
        FormRun formRun = sender.formRun();

        FormDataSource TAMRebateDate_DS = formRun.dataSource(formDataSourceStr(TAMRebateDeal, TAMRebateDate)) as FormDataSource;

        TAMRebateDate_DS.write();
    }

    /// <summary>
    /// Bug 284448: CB705 - Vendor Claims external data source does not link the transaction to METExternalSellData table
    /// Transaction type not editable when use external sales data
    /// </summary>
    /// <param name="sender">FormDataObject</param>
    /// <param name="e">FormDataFieldEventArgs</param>
    [FormDataFieldEventHandler(formDataFieldStr(TAMRebateDeal, TAMRebateDeal, METUseExternalSellData), FormDataFieldEventType::Modified)]
    public static void METUseExternalSellData_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource rebateDeal_ds = sender.datasource();        
        FormRun formRun = rebateDeal_ds.formRun();

        if (formHasMethod(formRun,formMethodStr(TAMRebateDeal, enableFields)))
        {
            formRun.enableFields();
        }
    }
